// One short, honest sentence naming what the booking actually is — mirrors
// the real activity_type values recorded across the app (BookNowWizard.tsx,
// TemplateBazaar.tsx, SubscriptionSignup.tsx, TempleRegister.tsx, Hero.tsx,
// lib/activities.ts's ActivityType union) so the invoice reads as the
// specific offering it is rather than one interchangeable line for every
// service. Never a ritual claim beyond what the booking itself provides —
// same restraint as TEMPLATE_TITLES/SHLOKA_BY_KIND above.
const SIGNIFICANCE_BY_ACTIVITY_TYPE: Record<string, string> = {
  puja: "A puja booked to be performed with devotion at your chosen temple, per the selected sankalpa.",
  seva: "A seva sponsorship supporting ongoing temple service and upkeep, offered in your name.",
  product: "A traditional offering item from the Sri Dwar Bazaar, sourced for devotional and ritual use.",
  wellness: "An enrollment in a Holistic Wellness & Yogic Sciences session or program.",
  other: "A Counselling & Guidance session booked with a Sri Dwar-affiliated expert.",
  darshan_certificate: "A Temple Visit / Darshan Certificate contribution, commemorating your visit.",
  contribution: "A voluntary contribution toward Sri Dwar's temple-preservation and community work.",
  temple_registration: "A temple or priest registration submission with Sri Dwar's network.",
  subscription: "A Refer & Earn subscription plan enrollment.",
};
function significanceLineFor(activityType: string | undefined): string | undefined {
  if (!activityType) return undefined;
  return SIGNIFICANCE_BY_ACTIVITY_TYPE[activityType];
}

// ═════════════════════════════════ RENDERING ════════════════════════════════
// A restrained repeating-petal mandala corner motif + thin gold hairline
// border keeps it premium and uncluttered — generous margins, one accent
// color family, one display face, one body face.

// ✅ ADDED 2026-08-28 — brand icon (temple mark only, no wordmark) on every
// certificate + invoice PDF, per request. Deliberately the icon-only crop of
// sridwar-logo.png, not the full logo-with-wordmark: the full logo's navy
// "SRI DWAR" text has poor contrast against the invoice's dark green header
// band, while the gold/saffron temple icon alone reads clearly on BOTH the
// certificate's cream background and the invoice's dark green band — so one
// asset works correctly in both templates without recoloring anything. The
// existing "SRI DWAR" text headers are left in place, unchanged; the icon is
// added alongside them, not a replacement.
//
// PNG alpha transparency (unlike the raster proxy used for outbound email)
// is fully respected by pdf-lib / every PDF viewer, so no baked-background
// compositing is needed here the way it was for emailtemplates.gs.
//
// ✅ FIX (2026-08-31 — verified against the actual public/ folder): this
// previously pointed at "public/images/sridwar-icon.png", which does not
// exist anywhere in the repository — fs.readFileSync was silently throwing,
// the catch below was silently swallowing it, and every certificate/invoice
// PDF has been rendering with NO logo mark at all. The only current PNG
// that is an icon-only mark (not the full icon+wordmark+tagline lockup in
// images/sridwar-logo.png, which would visually duplicate the "SRI DWAR"
// wordmark and tagline this file already draws as separate text right next
// to it) is android-chrome-512x512.png — the same mark already used for the
// site's favicon/PWA icons (see index.html's own <link> tags) — and it
// lives at the public ROOT, not under images/.
let cachedBrandIconBytes: Buffer | null | undefined;
function loadBrandIconBytes(): Buffer | null {
  if (cachedBrandIconBytes !== undefined) return cachedBrandIconBytes;
  try {
    const iconPath = path.join(
      process.cwd(),
      process.env.NODE_ENV === "production" ? "dist" : "public",
      "android-chrome-512x512.png"
    );
    cachedBrandIconBytes = fs.readFileSync(iconPath);
  } catch {
    console.warn(
      "[certificateService] Brand icon not found at public/android-chrome-512x512.png (or dist/ in prod) — PDFs will render without it."
    );
    cachedBrandIconBytes = null;
  }
  return cachedBrandIconBytes;
}

// ✅ ADDED — website QR code in the invoice footer, reusing the existing
// SridwarQR artwork already in the website's images (src/assets/images/
// SridwarQR.jpg). Read from the same public/images (dist/images in prod)
// location every other server-rendered asset in this file uses — see
// loadBrandIconBytes above for the identical dev/prod path pattern.
// Exactly as defensive as that loader: a missing/renamed file must never
// block a devotee's invoice from generating, so failures just log and the
// invoice renders without the QR block. NOTE: this assumes the file is
// deployed to public/images/SridwarQR.jpg — confirm that filename/path
// against the actual public/ folder (not included in this review) before
// relying on this; if it differs, update the path below.
let cachedQrCodeBytes: Buffer | null | undefined;
function loadQrCodeBytes(): Buffer | null {
  if (cachedQrCodeBytes !== undefined) return cachedQrCodeBytes;
  try {
    const qrPath = path.join(
      process.cwd(),
      process.env.NODE_ENV === "production" ? "dist" : "public",
      "images",
      "SridwarQR.jpg"
    );
    cachedQrCodeBytes = fs.readFileSync(qrPath);
  } catch {
    console.warn(
      "[certificateService] Website QR code not found at public/images/SridwarQR.jpg (or dist/images/ in prod) — invoices will render without it."
    );
    cachedQrCodeBytes = null;
  }
  return cachedQrCodeBytes;
}

async function drawMandalaCorner(page: PDFPage, x: number, y: number, scale = 1) {
  // A restrained eight-petal lotus flourish, not a full starburst — reads as
  // an ornamental corner accent rather than competing with the certificate text.
  const petal = (r: number) =>
    `M 0 0 C ${r * 0.35} ${r * 0.12}, ${r * 0.45} ${r * 0.55}, 0 ${r} C ${-r * 0.45} ${r * 0.55}, ${-r * 0.35} ${r * 0.12}, 0 0 Z`;
  for (let i = 0; i < 8; i++) {
    page.drawSvgPath(petal(20 * scale), {
      x,
      y,
      scale,
      rotate: degrees(i * 45),
      color: BRAND.saffron,
      opacity: 0.22,
      borderColor: BRAND.gold,
      borderWidth: 0.5,
      borderOpacity: 0.7,
    });
  }
  page.drawEllipse({ x, y, xScale: 3.2 * scale, yScale: 3.2 * scale, color: BRAND.saffron });
  page.drawEllipse({ x, y, xScale: 6 * scale, yScale: 6 * scale, borderColor: BRAND.gold, borderWidth: 0.75 });
}

async function drawFrame(page: PDFPage) {
  const { width, height } = page.getSize();
  const margin = 24;
  // outer deep border
  page.drawRectangle({
    x: margin,
    y: margin,
    width: width - margin * 2,
    height: height - margin * 2,
    borderColor: BRAND.darkGreen,
    borderWidth: 1.4,
  });
  // inner hairline (creates the "generous whitespace" band premium certs use)
  page.drawRectangle({
    x: margin + 10,
    y: margin + 10,
    width: width - (margin + 10) * 2,
    height: height - (margin + 10) * 2,
    borderColor: BRAND.gold,
    borderWidth: 0.6,
  });
  await drawMandalaCorner(page, margin + 10, height - margin - 10);
  await drawMandalaCorner(page, width - margin - 10, height - margin - 10);
  await drawMandalaCorner(page, margin + 10, margin + 10);
  await drawMandalaCorner(page, width - margin - 10, margin + 10);
}

function centeredText(
  page: PDFPage,
  text: string,
  y: number,
  font: PDFFont,
  size: number,
  color: RGB = BRAND.darkGreen
) {
  const { width } = page.getSize();
  const textWidth = font.widthOfTextAtSize(text, size);
  page.drawText(text, { x: (width - textWidth) / 2, y, size, font, color });
}

/** Like centeredText, but centered on an arbitrary x (not the whole page) — used for the QR caption. */
function centeredTextAt(page: PDFPage, text: string, centerX: number, y: number, font: PDFFont, size: number, color: RGB) {
  const textWidth = font.widthOfTextAtSize(text, size);
  page.drawText(text, { x: centerX - textWidth / 2, y, size, font, color });
}

// ✅ ADDED — shrink-to-fit + truncate for dynamic, devotee-submitted text
// (a devotee's own name, a Bazaar product name, a deity/temple name) whose
// length is never bounded by us. Every OTHER text draw in this file is
// either a fixed short label or already passed through pdf-lib's own
// `maxWidth` wrapping (see drawWrapped/contactLine below) — these two were
// the only dynamic-length lines with no protection at all, so a long name
// or product title could previously run past the certificate's ornamental
// frame, or collide with the invoice's amount column. Uses pdf-lib's own
// `font.widthOfTextAtSize()` — the exact glyph metrics already embedded in
// the PDF — rather than a guessed average character width, so this is
// precise, not approximate.
function fitTextWidth(font: PDFFont, text: string, maxWidth: number, startSize: number, minSize: number): { text: string; size: number } {
  let size = startSize;
  while (size > minSize && font.widthOfTextAtSize(text, size) > maxWidth) size -= 0.5;
  if (font.widthOfTextAtSize(text, size) <= maxWidth) return { text, size };
  // Still too wide even at the floor size — truncate with an ellipsis,
  // never let dynamic text cross a hard boundary (frame edge, amount column).
  let truncated = text;
  while (truncated.length > 1 && font.widthOfTextAtSize(`${truncated}…`, size) > maxWidth) {
    truncated = truncated.slice(0, -1);
  }
  return { text: `${truncated.trimEnd()}…`, size };
}

/** centeredText, but shrinks (then truncates) dynamic text to always fit within maxWidth. */
function centeredTextFit(
  page: PDFPage,
  text: string,
  y: number,
  font: PDFFont,
  startSize: number,
  minSize: number,
  maxWidth: number,
  color: RGB = BRAND.darkGreen
) {
  const { width } = page.getSize();
  const fitted = fitTextWidth(font, text, maxWidth, startSize, minSize);
  const textWidth = font.widthOfTextAtSize(fitted.text, fitted.size);
  page.drawText(fitted.text, { x: (width - textWidth) / 2, y, size: fitted.size, font, color });
}

/** Left-aligned text that shrinks (then truncates) dynamic text to always fit within maxWidth. */
function leftTextFit(
  page: PDFPage,
  text: string,
  x: number,
  y: number,
  font: PDFFont,
  startSize: number,
  minSize: number,
  maxWidth: number,
  color: RGB
) {
  const fitted = fitTextWidth(font, text, maxWidth, startSize, minSize);
  page.drawText(fitted.text, { x, y, size: fitted.size, font, color });
}

async function renderCertificatePdf(kind: TemplateKind, fields: MergedFields): Promise<Uint8Array> {
  const doc = await PDFDocument.create();
  const page = doc.addPage([595.28, 419.53]); // A5 landscape — premium certificate proportions
  const serif = await doc.embedFont(StandardFonts.TimesRomanBold);
  const serifRegular = await doc.embedFont(StandardFonts.TimesRoman);
  const serifItalic = await doc.embedFont(StandardFonts.TimesRomanItalic);
  const { width, height } = page.getSize();

  page.drawRectangle({ x: 0, y: 0, width, height, color: BRAND.cream });
  await drawFrame(page);

  const iconBytes = loadBrandIconBytes();
  if (iconBytes) {
    try {
      const iconImage = await doc.embedPng(iconBytes);
      const iconH = 24;
      const iconW = iconImage.width * (iconH / iconImage.height);
      page.drawImage(iconImage, { x: (width - iconW) / 2, y: height - 36 - iconH, width: iconW, height: iconH });
    } catch {
      // Corrupt/unexpected asset — never let a bad logo file break certificate generation.
    }
  }

  centeredText(page, BRAND.name.toUpperCase(), height - 76, serif, 14, BRAND.darkGreen);
  centeredText(page, BRAND.tagline, height - 93, serifItalic, 9, BRAND.textMuted);

  centeredText(page, TEMPLATE_TITLES[kind], height - 140, serif, 22, BRAND.saffron);

  const bodyLine1 =
    kind === "booking_confirmation"
      ? `This confirms that ${fields.devoteeName}'s booking for`
      : `This is to certify that ${fields.devoteeName}'s`;
  centeredTextFit(page, bodyLine1, height - 190, serifRegular, 13, 9, width - 68);

  const serviceLine = fields.deityOrTempleName
    ? `${fields.serviceName} — ${fields.deityOrTempleName}`
    : fields.serviceName;
  centeredTextFit(page, serviceLine, height - 215, serif, 16, 10, width - 68, BRAND.darkGreen);

  const bodyLine2 =
    kind === "booking_confirmation"
      ? `has been received and confirmed as of ${fields.date}.`
      : `was performed with devotion on ${fields.date}.`;
  centeredText(page, bodyLine2, height - 240, serifRegular, 13);

  // ✅ ADDED 2026-08-28 — compact devotional footer: shloka (ASCII-safe —
  // see SHLOKA_BY_KIND comment) + a one-line mention of three other
  // offerings + a subtle, always-voluntary Stone-Name Engraving note. Kept
  // to three short single lines (no wrapping) so the certificate's premium,
  // uncluttered A5 layout is preserved — the fuller versions of this same
  // wording live in the email (buildEmailPayload) and invoice (below).
  const shloka = SHLOKA_BY_KIND[kind];
  centeredText(page, `"${shloka.translitAscii}" — ${shloka.attribution}`, height - 262, serifItalic, 7.5, BRAND.textMuted);
  centeredText(page, RELATED_SERVICES_LINE, height - 275, serifRegular, 6.5, BRAND.textMuted);
  centeredText(page, STONE_ENGRAVING_LINE_PDF_COMPACT, height - 286, serifItalic, 6, BRAND.textMuted);

  centeredText(page, `Reference: ${fields.referenceId}`, 70, serifRegular, 10, BRAND.textMuted);
  centeredText(page, "sridwar.com", 55, serifItalic, 9, BRAND.textMuted);

  return doc.save();
}

// ═══════════════════════════ INVOICE (payment-confirmed) ════════════════════
// Itemized, A4 portrait, table-style layout — structurally the same idea as
// an Amazon/Flipkart order invoice (seller block, invoice #, bill-to,
// line-item table, subtotal → total, payment status stamp, terms footer),
// adapted to Sri Dwar's own brand palette. Used ONLY for kind ===
// "booking_confirmation" — i.e. only ever reached after runPipeline's guard
// has already re-verified payment_status === 'confirmed' server-side. The
// puja/seva/darshan certificate templates never call this function.
async function renderInvoicePdf(fields: MergedFields): Promise<Uint8Array> {
  const doc = await PDFDocument.create();
  const page = doc.addPage([595.28, 841.89]); // A4 portrait
  const { width, height } = page.getSize();
  const sans = await doc.embedFont(StandardFonts.Helvetica);
  const sansBold = await doc.embedFont(StandardFonts.HelveticaBold);
  const italic = await doc.embedFont(StandardFonts.HelveticaOblique);
  const margin = 48;
  const contentWidth = width - margin * 2;
  let y = height - margin;

  const text = (
    t: string,
    x: number,
    yy: number,
    opts: { size?: number; font?: PDFFont; color?: RGB; align?: "left" | "right" } = {}
  ) => {
    const size = opts.size ?? 10;
    const font = opts.font ?? sans;
    const color = opts.color ?? BRAND.darkGreen;
    const drawX = opts.align === "right" ? x - font.widthOfTextAtSize(t, size) : x;
    page.drawText(t, { x: drawX, y: yy, size, font, color });
  };
  const rule = (yy: number, color: RGB = BRAND.gold, thickness = 0.75) =>
    page.drawRectangle({ x: margin, y: yy, width: contentWidth, height: thickness, color });

  // ── Header band: brand + document title ──────────────────────────────────
  page.drawRectangle({ x: 0, y: height - 96, width, height: 96, color: BRAND.darkGreen });

  // ✅ ADDED 2026-08-28 — brand icon beside the existing wordmark text (see
  // loadBrandIconBytes comment above for why it's the icon-only crop).
  // headerTextX only shifts right of `margin` when the icon actually draws,
  // so a missing/failed asset falls back to the exact original layout.
  let headerTextX = margin;
  const iconBytes = loadBrandIconBytes();
  if (iconBytes) {
    try {
      const iconImage = await doc.embedPng(iconBytes);
      const iconH = 34;
      const iconW = iconImage.width * (iconH / iconImage.height);
      page.drawImage(iconImage, { x: margin, y: height - 62, width: iconW, height: iconH });
      headerTextX = margin + iconW + 12;
    } catch {
      // Corrupt/unexpected asset — never let a bad logo file break invoice generation.
    }
  }

  text(BRAND.name.toUpperCase(), headerTextX, height - 42, { size: 20, font: sansBold, color: BRAND.white });
  text(BRAND.tagline, headerTextX, height - 60, { size: 9, font: sans, color: BRAND.gold });
  text("PAYMENT CONFIRMATION / INVOICE", width - margin, height - 42, {
    size: 13,
    font: sansBold,
    color: BRAND.white,
    align: "right",
  });
  text("Shradhalu Private Limited", width - margin, height - 60, { size: 9, font: sans, color: BRAND.gold, align: "right" });
  text("Jajpur Road, Odisha, India", width - margin, height - 73, { size: 9, font: sans, color: BRAND.gold, align: "right" });
  y = height - 96 - 32;

  // ── Invoice meta + Bill To, two columns ──────────────────────────────────
  text("BILL TO", margin, y, { size: 8, font: sansBold, color: BRAND.textMuted });
  text("INVOICE DETAILS", width / 2 + 10, y, { size: 8, font: sansBold, color: BRAND.textMuted });
  y -= 16;
  leftTextFit(page, fields.devoteeName, margin, y, sansBold, 12, 8, width / 2 - margin - 6, BRAND.darkGreen);
  text(`Invoice #: ${fields.invoiceNumber}`, width / 2 + 10, y, { size: 10, font: sans });
  y -= 15;
  text(`Reference: ${fields.referenceId}`, width / 2 + 10, y, { size: 10, font: sans });
  y -= 15;
  text(`Date: ${fields.date}`, width / 2 + 10, y, { size: 10, font: sans });
  y -= 28;
  rule(y);
  y -= 24;

  // ── Line-item table ───────────────────────────────────────────────────────
  const col2 = width - margin - 110; // amount column, right-aligned
  text("DESCRIPTION", margin, y, { size: 8, font: sansBold, color: BRAND.textMuted });
  text("AMOUNT", width - margin, y, { size: 8, font: sansBold, color: BRAND.textMuted, align: "right" });
  y -= 10;
  rule(y);
  y -= 20;

  const serviceLine = fields.deityOrTempleName ? `${fields.serviceName} — ${fields.deityOrTempleName}` : fields.serviceName;
  leftTextFit(page, serviceLine, margin, y, sansBold, 11, 8, contentWidth - 140, BRAND.darkGreen);
  text(formatRupees(fields.amount ?? 0), width - margin, y, { size: 11, font: sans, align: "right" });
  y -= 16;

  // ✅ ADDED — service-specific significance line (see
  // SIGNIFICANCE_BY_ACTIVITY_TYPE) so this invoice reads as the actual
  // offering it is, not one interchangeable line for every service type.
  // Falls back to nothing (not a fabricated sentence) for an
  // activity_type this map doesn't yet cover.
  const significance = significanceLineFor(fields.activityType);
  if (significance) {
    text(significance, margin, y, { size: 8.5, font: italic, color: BRAND.textMuted });
    y -= 14;
  }

  y -= 10;
  rule(y, BRAND.textMuted, 0.5);
  y -= 22;

  // ── Totals block, right-aligned ──────────────────────────────────────────
  const totalsRow = (label: string, value: string, opts: { bold?: boolean; color?: RGB } = {}) => {
    text(label, col2 - 90, y, { size: 10, font: opts.bold ? sansBold : sans, color: opts.color ?? BRAND.darkGreen });
    text(value, width - margin, y, { size: 10, font: opts.bold ? sansBold : sans, color: opts.color ?? BRAND.darkGreen, align: "right" });
    y -= 16;
  };
  totalsRow("Subtotal", formatRupees(fields.amount ?? 0));
  if (typeof fields.taxAmount === "number") totalsRow("Tax", formatRupees(fields.taxAmount));
  if (typeof fields.platformFee === "number") totalsRow("Platform / convenience fee", formatRupees(fields.platformFee));
  if (typeof fields.discountAmount === "number") totalsRow("Discount", `- ${formatRupees(fields.discountAmount)}`);
  y -= 4;
  rule(y);
  y -= 20;
  text("TOTAL PAID", col2 - 90, y, { size: 13, font: sansBold, color: BRAND.darkGreen });
  text(formatRupees(fields.totalAmount ?? fields.amount ?? 0), width - margin, y, {
    size: 13,
    font: sansBold,
    color: BRAND.darkGreen,
    align: "right",
  });
  y -= 34;

  // ── Payment method + status stamp ────────────────────────────────────────
  text(`Payment Method: ${fields.paymentMethodLabel ?? "UPI"}`, margin, y, { size: 10, font: sans });
  const stampLabel = "PAYMENT CONFIRMED";
  const stampFontSize = 8.5;
  const stampTextWidth = sansBold.widthOfTextAtSize(stampLabel, stampFontSize);
  const stampBoxWidth = stampTextWidth + 20; // 10px padding each side
  page.drawRectangle({ x: width - margin - stampBoxWidth, y: y - 6, width: stampBoxWidth, height: 22, color: rgb(0.09, 0.42, 0.24) });
  text(stampLabel, width - margin - 10, y, { size: stampFontSize, font: sansBold, color: BRAND.white, align: "right" });
  y -= 40;

  // ── Footer: disclaimer / terms ────────────────────────────────────────────
  rule(y);
  y -= 16;
  const disclaimer =
    "Offerings and sevas are performed with devotion as per temple process. Timings may vary depending on temple " +
    "schedule, festival rush, priest availability, and temple rituals. This document confirms receipt of payment as " +
    "recorded above and serves as your official proof of booking/payment. For queries, contact puja@sridwar.com.";

  const drawWrapped = (t: string, size: number, useFont: PDFFont, color: RGB, lineGap: number) => {
    const words = t.split(" ");
    let line = "";
    for (const word of words) {
      const candidate = line ? `${line} ${word}` : word;
      if (useFont.widthOfTextAtSize(candidate, size) > contentWidth) {
        text(line, margin, y, { size, font: useFont, color });
        y -= lineGap;
        line = word;
      } else {
        line = candidate;
      }
    }
    if (line) {
      text(line, margin, y, { size, font: useFont, color });
      y -= lineGap;
    }
  };

  drawWrapped(disclaimer, 8, italic, BRAND.textMuted, 11);

  // ✅ ADDED 2026-08-28 — devotional footer: shloka (ASCII-safe transliteration
  // + English meaning — see SHLOKA_BY_KIND comment for why no Devanagari is
  // drawn here), the 3-other-offerings note, and the voluntary Stone-Name
  // Engraving mention. This invoice always uses the "booking_confirmation"
  // shloka (payment/offering-themed), since it's the only kind rendered here.
  y -= 6;
  const invoiceShloka = SHLOKA_BY_KIND.booking_confirmation;
  drawWrapped(`"${invoiceShloka.translitAscii}" — ${invoiceShloka.attribution}. "${invoiceShloka.meaning}"`, 8, italic, BRAND.darkGreen, 11);
  y -= 4;
  drawWrapped(RELATED_SERVICES_LINE, 8, sans, BRAND.textMuted, 11);
  y -= 4;
  drawWrapped(STONE_ENGRAVING_LINE_PDF, 8, italic, BRAND.textMuted, 11);

  // ✅ ADDED — contact/social line + website QR, sourced from the same real
  // handles already published on the live site's footer (Navbar.tsx):
  // Instagram, Facebook, YouTube, and the official WhatsApp helpline link.
  // Deliberately no phone number, matching the rest of Sri Dwar's contact
  // surfaces. QR code is optional/defensive — see loadQrCodeBytes above.
  y -= 6;
  const qrBytes = loadQrCodeBytes();
  let footerTextWidth = contentWidth;
  if (qrBytes) {
    try {
      const qrImage = await doc.embedJpg(qrBytes);
      const qrSize = 46;
      footerTextWidth = contentWidth - qrSize - 12;
      const qrX = width - margin - qrSize;
      page.drawImage(qrImage, { x: qrX, y: y - qrSize + 8, width: qrSize, height: qrSize });
      centeredTextAt(page, "Scan to visit", qrX + qrSize / 2, y - qrSize - 2, sans, 6, BRAND.textMuted);
    } catch {
      // Corrupt/unexpected asset — never let a bad QR file break invoice generation.
    }
  }
  const contactLine1 = "Shradhalu Private Limited · sridwar.com · puja@sridwar.com";
  const contactLine2 = "WhatsApp: wa.me/message/325QR2O5II3IH1 · Instagram/Facebook/YouTube: @sridwar";
  page.drawText(contactLine1, { x: margin, y, size: 8, font: sans, color: BRAND.textMuted, maxWidth: footerTextWidth });
  y -= 11;
  page.drawText(contactLine2, { x: margin, y, size: 8, font: sans, color: BRAND.textMuted, maxWidth: footerTextWidth });

  return doc.save();
}

// ═══════════════════════════════ EMAIL PAYLOAD ══════════════════════════════
// Actual delivery reuses the same pattern already in production (Config.gs /
// EmailSender.gs) — this just builds the payload; sending is one fetch() to
// your existing Apps Script Web App URL. If that env var isn't set yet, the
// PDF is still generated/stored/audited — email is skipped, not fatal.

interface CertificateEmailPayload {
  to: string;
  subject: string;
  bodyHtml: string;
  attachmentBase64: string;
  attachmentFilename: string;
  // ─── Added for Webhook.gs (Apps Script) ────────────────────────────────
  // Webhook.gs requires refId + emailType on every request: refId feeds the
  // SAME dedupe log every other email in the project uses (so a retry can
  // never double-send), and emailType must be one of the two values in its
  // allow-list. These are deliberately namespaced with a "webhook_invoice_"
  // prefix so they can never collide with the Sheets-driven flow's own
  // "certificate_ready" / "booking" emailType values in that shared log.
  refId: string;
  emailType: "webhook_invoice_booking_confirmed" | "webhook_invoice_certificate_ready";
}

function buildEmailPayload(
  eventType: EventType,
  kind: TemplateKind,
  fields: MergedFields,
  toEmail: string,
  pdfBytes: Uint8Array
): CertificateEmailPayload {
  const subject =
    eventType === "booking_confirmed"
      ? `Sri Dwar — Payment Confirmed & Invoice (${fields.referenceId})`
      : `Sri Dwar — Your ${TEMPLATE_TITLES[kind]} is Ready`;

  const bodyHtml = `
    <div style="font-family:Georgia,serif;background:#fbf6ec;padding:24px;color:#0c2b26;">
      <h2 style="color:#0c2b26;">${subject}</h2>
      <p>Dear ${fields.devoteeName},</p>
      <p>${
        eventType === "booking_confirmed"
          ? `Your payment for <strong>${fields.serviceName}</strong> has been received and confirmed. The attached PDF is your official invoice and payment confirmation — please keep it as proof of your booking.`
          : `Your <strong>${TEMPLATE_TITLES[kind]}</strong> for <strong>${fields.serviceName}</strong> is attached, performed on ${fields.date}.`
      }</p>
      ${
        eventType === "booking_confirmed" && typeof fields.totalAmount === "number"
          ? `<p style="font-size:15px;"><strong>Amount Paid: ₹${fields.totalAmount.toLocaleString("en-IN", {
              minimumFractionDigits: 2,
            })}</strong> via ${fields.paymentMethodLabel ?? "UPI"}</p>`
          : ""
      }
      <p style="color:#6b7a76;font-size:13px;">Reference: ${fields.referenceId}${
    fields.invoiceNumber ? ` · Invoice: ${fields.invoiceNumber}` : ""
  }<br/>Sri Dwar — Connect. Contribute. Preserve.</p>
      ${(() => {
        // ✅ ADDED 2026-08-28 — same devotional footer added to the GAS email
        // templates (emailtemplates.gs) and the client-side confirmation
        // (devotionalMessages.ts): a shloka matched to what this email is
        // actually about, a brief non-promotional 3-services note, and a
        // subtle, always-voluntary Stone-Name Engraving mention. No font
        // constraint here (this is HTML, not pdf-lib), so the full
        // Devanagari + IAST transliteration is shown, unlike the PDF above.
        const s = SHLOKA_BY_KIND[kind];
        return `
      <div style="margin-top:18px;padding:14px 16px;background:#fbf6ec;border-left:3px solid #e8a33d;border-radius:0 8px 8px 0;">
        <div style="font-size:15px;color:#0c2b26;font-weight:bold;">${s.sa}</div>
        <div style="font-size:11px;color:#6b7a76;font-style:italic;margin-top:2px;">${s.translit}</div>
        <div style="font-size:12px;color:#444;margin-top:6px;line-height:1.6;">&#8220;${s.meaning}&#8221; — ${s.attribution}</div>
      </div>
      <div style="font-size:12px;color:#444;line-height:1.7;margin-top:16px;">${RELATED_SERVICES_LINE_HTML}</div>
      <div style="font-size:11px;color:#6b7a76;line-height:1.7;margin-top:14px;padding-top:12px;border-top:1px dashed #e7ddc7;">${STONE_ENGRAVING_LINE_HTML}</div>`;
      })()}
    </div>`;

  return {
    to: toEmail,
    subject,
    bodyHtml,
    attachmentBase64: Buffer.from(pdfBytes).toString("base64"),
    attachmentFilename: `${fields.referenceId}-${kind}.pdf`,
    refId: fields.referenceId,
    emailType: eventType === "booking_confirmed" ? "webhook_invoice_booking_confirmed" : "webhook_invoice_certificate_ready",
  };
}

interface DispatchEmailResult {
  status: "sent" | "skipped";
  /**
   * ✅ DIAGNOSTIC FIX (2026-08-16): previously this function returned a bare
   * "skipped" string for THREE completely different situations —
   *   1. GAS_EMAIL_WEBHOOK_URL not set on this server at all (email sending
   *      fully disabled, on purpose, per the original "wire trigger later"
   *      scope note at the top of this file)
   *   2. Webhook.gs itself declining to send (its own dedupe log already
   *      shows this refId+emailType as sent, an invalid-looking recipient
   *      address, or the daily quota being exhausted)
   *   3. (previously) no distinction at all in certificate_audit_log —
   *      every "email_skipped" row looked identical, so there was no way
   *      to tell "email sending isn't even configured yet" apart from
   *      "email sending is configured and is deliberately holding back."
   * This made the single most common real-world failure — a booking's PDF
   * generates fine, the row shows "generated" in every log, and yet the
   * devotee never receives anything — genuinely impossible to diagnose
   * from the audit log alone. `reason` is now carried through into
   * certificate_audit_log's `detail` column (see runPipeline below) so the
   * exact cause is visible without guessing.
   */
  reason?: string;
}

async function dispatchEmail(payload: CertificateEmailPayload): Promise<DispatchEmailResult> {
  const webhookUrl = process.env.GAS_EMAIL_WEBHOOK_URL;
  const webhookSecret = process.env.EMAIL_WEBHOOK_SECRET;
  if (!webhookUrl) {
    // deliberate — see file header — but now labeled, not silent.
    return {
      status: "skipped",
      reason: "GAS_EMAIL_WEBHOOK_URL is not set on this server. No email was even attempted. Set it, on Render, to your Apps Script Web App's /exec URL (see Webhook.gs setup steps).",
    };
  }
  if (!webhookSecret) {
    // Fail loudly, not silently: a missing secret is a config mistake, not
    // an intentional "email disabled" state like a missing webhookUrl is.
    throw new CertificateError(
      "GAS_EMAIL_WEBHOOK_URL is set but EMAIL_WEBHOOK_SECRET is not — Webhook.gs will reject every request without it.",
      "config_missing"
    );
  }
  const res = await fetch(webhookUrl, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ ...payload, secret: webhookSecret }),
  });
  if (!res.ok) throw new CertificateError(`Email webhook responded ${res.status}`, "email_error");
  const json = (await res.json()) as { ok: boolean; sent?: boolean; error?: string };
  if (!json.ok) throw new CertificateError(`Email webhook rejected the request: ${json.error}`, "email_error");
  if (json.sent) return { status: "sent" };
  // Webhook.gs's own dedupe/quota/validity logic held it back — see
  // sendBrandedEmail_() in EmailSender.gs for the exact possible causes.
  return {
    status: "skipped",
    reason: "Webhook.gs received the request and returned ok, but did not actually send (its own dedupe log, invalid-looking email address, or daily quota). Check Email_Send_Log / Email_Errors in the tracking spreadsheet for this refId.",
  };
}

